select p.code,
  count(*) planned_bases, sum(p.nvar) planned_new_cards,
  count(*) filter (where c.id is not null and c.name_zh = p.name_zh and c.official_card_number = p.num and tw.n = 1 and tw.code = p.code and tw.num = p.num and tw.ids = p.ids
    and (c.source = 'tcgdex-zh-tw' or c.provider_id = p.ids->>0)
    and not exists (select 1 from card_images i where i.card_id = c.id) and (tw.img is null or tw.img = '')) as base_ok,
  count(*) filter (where exists (select 1 from tcg_cards x where x.id in (select card_id from v) and x.id like p.base_id || '-v%')) as new_ids_existing,
  count(*) filter (where exists (select 1 from tcg_cards x where x.source = 'asia-pokemon-card-official-tw' and x.id <> p.base_id and x.provider_id in (select jsonb_array_elements_text(p.ids)))) as official_id_used_by_other_card
from plan p
left join tcg_cards c on c.id = p.base_id
left join lateral (select count(*) n, min(g.local_set_code) code, min(g.local_card_number) num, (array_agg(g.metadata->'officialDetailIds'))[1] ids, min(g.image_url) img from tcg_printings g where g.card_id = p.base_id and g.region = 'TW') tw on true
group by p.code order by p.code
